-- ── khld_partner (entity) ──

create table public.khld_partner (
  id                    uuid primary key default gen_random_uuid(),
  municipality_id       uuid not null references public.municipality(id) default public.my_municipality(),
  name                  text not null,
  partner_type_id       uuid references public.ref_khld_partner_type(id),
  partner_type_other    text,
  contact               text,
  client_uuid           uuid unique,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  created_by            uuid references auth.users(id) default auth.uid(),
  deleted_at            timestamptz,
  constraint khld_partner_id_municipality_key unique (id, municipality_id)
);
create index khld_partner_municipality_idx on public.khld_partner (municipality_id);
create index khld_partner_created_by_idx on public.khld_partner (created_by);
create index khld_partner_partner_type_id_idx on public.khld_partner (partner_type_id);
create unique index khld_partner_name_key on public.khld_partner (municipality_id, lower(btrim(name)));
comment on column public.khld_partner.name is 'Name of partner organisation (SO1-0 field 3; SO1-A3 contributor)';
comment on column public.khld_partner.partner_type_id is 'Partner type (SO1-0 field 4)';
comment on column public.khld_partner.partner_type_other is 'free text for partner_type';
comment on column public.khld_partner.contact is 'Phone and email (SO1-0 field 7)';
create trigger trg_khld_partner_other before insert or update on public.khld_partner
