-- ── khld_market (h1, KHLD-SO4-H1) ──

create table public.khld_market (
  id                    uuid primary key default gen_random_uuid(),
  municipality_id       uuid not null references public.municipality(id) default public.my_municipality(),
  reference             text,
  market_name           text not null,
  market_date           date not null,
  occasion_id           uuid not null references public.ref_khld_h1_occasion(id),
  occasion_other        text,
  phase_id              uuid not null references public.ref_khld_h1_phase(id),
  times_from            text,
  times_to              text,
  location_id           uuid not null references public.ref_khld_h1_location(id),
  location_other        text,
  permit_reference      text,
  permit_date           date,
  stalls_offered        int not null,
  stalls_occupied       int not null,
  announcement_days_before int,
  applications_received int not null,
  applications_accepted int,
  applications_declined int,
  decline_reason        text,
  selection_method_id   uuid not null references public.ref_khld_h1_selection_method(id),
  fee_charged           boolean not null,
  fee_per_stall_jod     numeric(12,3),
  fee_basis             text,
  refreshment_point_id  uuid references public.ref_khld_h1_refreshment_point(id),
  refreshment_point_other text,
  accessibility_id      uuid not null references public.ref_khld_h1_accessibility(id),
  accessibility_other   text,
  visitors_estimated    int not null,
  visitors_method_id    uuid references public.ref_khld_h1_visitors_method(id),
  hygiene_check_id      uuid not null references public.ref_khld_h1_hygiene_check(id),
  hygiene_check_other   text,
  total_sales_jod       numeric(12,3) not null,
  total_sales_method_id uuid references public.ref_khld_h1_total_sales_method(id),
  cash_cost_jod         numeric(12,3) not null,
  cash_source_id        uuid references public.ref_khld_h1_cost_source(id),
  inkind_value_jod      numeric(12,3),
  inkind_provider       text,
  feedback_collected_id uuid not null references public.ref_khld_h1_feedback_collected(id),
  vendor_forms          int,
  visitor_forms         int,
  lessons               text not null,
  recorded_by_name      text,
  recorded_on           date,
  verified_by_name      text,
  verified_on           date,
  is_published          boolean not null default false,
  client_uuid           uuid unique,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  created_by            uuid references auth.users(id) default auth.uid(),
  deleted_at            timestamptz,
  constraint khld_market_id_municipality_key unique (id, municipality_id),
  constraint khld_market_reference_key unique (municipality_id, reference)
);
create index khld_market_municipality_idx on public.khld_market (municipality_id);
create index khld_market_created_by_idx on public.khld_market (created_by);
create index khld_market_occasion_id_idx on public.khld_market (occasion_id);
create index khld_market_phase_id_idx on public.khld_market (phase_id);
create index khld_market_location_id_idx on public.khld_market (location_id);
create index khld_market_selection_method_id_idx on public.khld_market (selection_method_id);
create index khld_market_refreshment_point_id_idx on public.khld_market (refreshment_point_id);
create index khld_market_accessibility_id_idx on public.khld_market (accessibility_id);
create index khld_market_visitors_method_id_idx on public.khld_market (visitors_method_id);
create index khld_market_hygiene_check_id_idx on public.khld_market (hygiene_check_id);
create index khld_market_total_sales_method_id_idx on public.khld_market (total_sales_method_id);
create index khld_market_cash_source_id_idx on public.khld_market (cash_source_id);
create index khld_market_feedback_collected_id_idx on public.khld_market (feedback_collected_id);
